"""A minimal renderer for the tiny subset of jinja used by scripts/apk/*.in."""
import re, sys, types

TOKEN = re.compile(r"({%.*?%}|{{.*?}})", re.S)

def resolve(expr, ctx):
    expr = expr.strip()
    obj = ctx
    for part in expr.split("."):
        if isinstance(obj, dict):
            obj = obj.get(part)
        else:
            obj = getattr(obj, part, None)
    return obj

def parse(tokens, i=0):
    node = []
    while i < len(tokens):
        t = tokens[i]
        if t.startswith("{%"):
            stmt = t[2:-2].strip()
            if stmt.startswith(("endfor", "endif", "else", "elif")):
                return node, i, stmt
            if stmt.startswith("for "):
                m = re.match(r"for\s+(\w+)\s+in\s+(.+)$", stmt)
                body, i, stmt2 = parse(tokens, i + 1)
                assert stmt2 == "endfor", stmt2
                node.append(("for", m.group(1), m.group(2), body))
            elif stmt.startswith("if "):
                branches = []
                cond = stmt[3:]
                while True:
                    body, i, stmt2 = parse(tokens, i + 1)
                    branches.append((cond, body))
                    if stmt2 == "endif":
                        break
                    assert stmt2.startswith(("elif", "else")), stmt2
                    cond = True if stmt2 == "else" else stmt2[5:]
                node.append(("if", branches))
            else:
                raise AssertionError("unsupported stmt: " + stmt)
        elif t.startswith("{{"):
            node.append(("expr", t[2:-2].strip()))
        else:
            node.append(("text", t))
        i += 1
    return node, i, None

def render(node, ctx, out):
    for kind, *rest in node:
        if kind == "text":
            out.append(rest[0])
        elif kind == "expr":
            v = resolve(rest[0], ctx)
            out.append("" if v is None else str(v))
        elif kind == "for":
            var, iterable, body = rest
            for item in resolve(iterable, ctx) or []:
                render(body, dict(ctx, **{var: item}), out)
        elif kind == "if":
            for cond, body in rest:
                if cond is True or resolve(cond, ctx):
                    render(body, ctx, out)
                    break

if __name__ == "__main__":
    sys.exit(0)
