"""Extract the bash code of the steps of a workflow for a syntax check."""
import sys, re

def steps(path):
    lines = open(path).read().split("\n")
    out, cur, in_run = {}, None, False
    for line in lines:
        m = re.match(r"^      - (?:name: (.+)|uses: (.+))$", line)
        if m:
            cur = (m.group(1) or m.group(2)).strip()
            out[cur] = []
            in_run = False
            continue
        if cur is None:
            continue
        if re.match(r"^        run: \|", line):
            in_run = True
            continue
        if in_run:
            if line.strip() == "" or line.startswith("          "):
                out[cur].append(line[10:])
            else:
                in_run = False
    return out

if __name__ == "__main__":
    path = sys.argv[1]
    import os
    os.makedirs("/tmp/verify/steps", exist_ok=True)
    for name, body in steps(path).items():
        if body:
            fn = "/tmp/verify/steps/" + re.sub(r"\W+", "_", name).strip("_") + ".sh"
            open(fn, "w").write("\n".join(body) + "\n")
            print(fn)
