"""A tiny YAML block-style parser, enough to validate GitHub workflow files."""
import re, sys


class YamlError(Exception):
    pass


def strip_comment(s):
    out, q = [], None
    for i, ch in enumerate(s):
        if q:
            out.append(ch)
            if ch == q:
                q = None
        elif ch in "\"'":
            q = ch
            out.append(ch)
        elif ch == "#" and (i == 0 or s[i - 1] in " \t"):
            break
        else:
            out.append(ch)
    return "".join(out).rstrip()


def scalar(s):
    s = s.strip()
    if s == "" or s == "null":
        return None
    if s[0] in "[{":          # flow collections are treated as opaque strings
        return s
    if s[0] in "\"'":
        return s[1:-1]
    return s


class Parser:
    def __init__(self, text):
        self.lines = text.split("\n")
        self.i = 0

    def peek(self):
        while self.i < len(self.lines):
            raw = self.lines[self.i]
            if "\t" in raw[: len(raw) - len(raw.lstrip())]:
                raise YamlError("tab used for indentation, line %d" % (self.i + 1))
            s = strip_comment(raw)
            if s.strip() == "":
                self.i += 1
                continue
            return self.i, len(raw) - len(raw.lstrip()), s.strip()
        return None

    def parse(self, indent):
        result = None
        while True:
            p = self.peek()
            if p is None:
                return result
            idx, ind, content = p
            if ind < indent:
                return result
            if ind > indent:
                raise YamlError("unexpected indent at line %d: %r" % (idx + 1, self.lines[idx]))
            if content.startswith("- ") or content == "-":
                if result is None:
                    result = []
                if not isinstance(result, list):
                    raise YamlError("mixed sequence/mapping at line %d" % (idx + 1))
                self.i += 1
                item = content[2:].strip()
                m = re.match(r"^([\w.$\"'-]+):\s*(.*)$", item)
                if m:  # inline mapping inside a sequence item
                    sub_indent = ind + 2
                    self.i -= 1
                    self.lines[self.i] = " " * sub_indent + item
                    result.append(self.parse(sub_indent))
                elif item == "":
                    result.append(self.parse_any(ind))
                else:
                    result.append(scalar(item))
            else:
                m = re.match(r"^([\w.$\"'-]+):(?:\s+(.*))?$", content)
                if not m:
                    raise YamlError("cannot parse line %d: %r" % (idx + 1, self.lines[idx]))
                if result is None:
                    result = {}
                if not isinstance(result, dict):
                    raise YamlError("mixed sequence/mapping at line %d" % (idx + 1))
                key, value = m.group(1), (m.group(2) or "")
                self.i += 1
                result[key] = self.value(value, ind)
                if result[key] is _BLOCK:
                    result[key] = self.parse(ind + 1) if self._more_than(ind) else None

    def _more_than(self, indent):
        p = self.peek()
        return p is not None and p[1] > indent

    def value(self, value, indent):
        value = value.strip()
        if value in ("|", "|-", "|+", ">", ">-", ">+"):
            # block scalar: consume deeper indented lines
            body = []
            while True:
                p = self.peek()
                if p is None or p[1] <= indent:
                    break
                body.append(self.lines[p[0]][indent + 1:])
                self.i += 1
            return "\n".join(body) + "\n"
        if value == "":
            return _BLOCK
        return scalar(value)


class _Block:
    pass


_BLOCK = _Block()


def load(text):
