    def format(self, partitions: Optional[int] = None, separator: str = '.', trim_zero: bool = False) -> str:
        versions: List[Optional[int]] = [self.major, self.minor, self.build, self.patch]

        if partitions is not None:
            versions = versions[:partitions]
        else:
            # Stop at None
            while versions and versions[-1] is None:
                versions.pop()

        # None to zero
        parts = list(part or 0 for part in versions)

        if trim_zero:
            while parts and parts[-1] == 0:
                parts.pop()

        return separator.join(str(part) for part in parts)

    def __str__(self) -> str:
        return self.format()

    # We use it for comparison. See: https://docs.python.org/3/reference/expressions.html#comparisons
    def to_tuple(self) -> Tuple[int, int, int, int]:
        if self.__tuple is not None:
            return self.__tuple

        self.__tuple = tuple(part or 0 for part in [self.major, self.minor, self.build, self.patch])
        return self.__tuple  # type: ignore[return-value]

    # Missing (None) partitions are treated as zero, see: to_tuple()
    @staticmethod
    def __compare_tuple(other: object) -> Optional[Tuple[int, int, int, int]]:
        if not isinstance(other, Version):
