    Version,
    ChromiumVersion,
    AndroidVersion,
    WindowsVersion,
)


class VersionRange:
    min_version: Optional[Version] = None
    max_version: Optional[Version] = None

    def __init__(self,
                 min_version: Union[Version, int, None] = None,
                 max_version: Union[Version, int, None] = None):
        self.min_version = Version(major=min_version) if isinstance(min_version, int) else min_version
        self.max_version = Version(major=max_version) if isinstance(max_version, int) else max_version

