    @staticmethod
    def __major(version: Optional[Version]) -> Optional[int]:
        if version is None:
            return None

        return version.major or 0

    def filter(self, versions: T_VERSIONS) -> T_VERSIONS:
        # TODO: Perhaps support for full version comparison, instead of just major versions
        min_major: Optional[int] = self.__major(self.min_version)
        max_major: Optional[int] = self.__major(self.max_version)

        tmp_versions: T_VERSIONS = []

        for version in versions:
            major: int = self.__major(version) or 0

            if min_major is not None and max_major is not None and min_major <= major <= max_major:
                tmp_versions.append(version)
            elif min_major is not None and max_major is None and min_major <= major:
                tmp_versions.append(version)
            elif min_major is None and max_major is not None and major <= max_major:
                tmp_versions.append(version)

        return tmp_versions

    def __repr__(self) -> str:
        return f"VersionRange(min_version={self.min_version}, max_version={self.max_version})"
