    def weighted_versions(self, weights: Optional[List[float]] = None, max_range: int = 4) -> None:
        if weights is None:
            weights = [1.0] * len(self.versions)
            for i in range(1, min(max_range, len(self.versions))):
                weights[-i] = 10.0 - i

